describe('Mark All Notifications as Read', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should mark all notifications as read with a single click', () => {
    // Verify notifications are visible and unread
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="unread-badge"]').should('be.visible');

    // Verify the "Mark All as Read" button is visible
    cy.get('[data-testid="mark-all-as-read-button"]').should('be.visible');
    cy.get('[data-testid="mark-all-as-read-button"]').should('contain', 'Mark All as Read');

    // Click the button
    cy.get('[data-testid="mark-all-as-read-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'All notifications marked as read');

    // Verify button state changes
    cy.get('[data-testid="mark-all-as-read-button"]').should('be.disabled');
    cy.get('[data-testid="mark-all-as-read-button"]').should('contain', 'All read');

    // Verify unread badge disappears from notifications
    cy.get('[data-testid="unread-badge"]').should('not.exist');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
  });

  it('should handle edge case when no notifications are present', () => {
    // Navigate to notifications with no items
    cy.visit('/notifications?empty=true');

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No notifications');

    // Verify "Mark All as Read" button does not appear or is disabled
    cy.get('[data-testid="mark-all-as-read-button"]').should('not.exist');

    // Verify no unread badges are present
    cy.get('[data-testid="unread-badge"]').should('not.exist');

    // Verify user can still interact with other notification features if available
    cy.get('[data-testid="filter-notifications"]').should('be.visible');
    cy.get('[data-testid="filter-notifications"]').click();
  });
});
